"""Builds the v2 datasets (author-written). Deterministic. Run from datasets/:  python build_v2_dataset.py

Files written to data/:
  cyber_qa.jsonl           defensive cybersecurity concepts (English + Hinglish)
  ai_ml_qa.jsonl           AI / ML / LLM concepts incl. training hygiene (English + Hinglish)
  change_requests.jsonl    "user says change X" -> structured request -> gate decision (generated by REAL change_policy)
  memory_decisions.jsonl   "user wrote this" -> should the assistant remember it?  (hand-labelled)
  search_grounding.jsonl   question + (synthetic) search results -> cited answer with FACT/INFERENCE/UNCERTAINTY
  feedback_events.jsonl    thumbs / corrections / style requests -> what the system may learn from them

Honest scope: answers are written by me from general knowledge. They are meant as a starting set to REVIEW and extend,
with the references named in each row. They are not a substitute for the official standards themselves.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "backend"))

from core.change_policy import ChangeRequest, evaluate_change  # noqa: E402

OUT = HERE / "data"
OUT.mkdir(exist_ok=True)
SRC = "author-written-v2"


def write(name: str, rows: list[dict]) -> None:
    with (OUT / name).open("w", encoding="utf-8", newline="\n") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(f"{name:26s} {len(rows):4d} rows")


