def qa_rows(items, prefix):
    return [{"id": f"{prefix}-{i:03d}", "topic": t, "lang": lang, "level": lvl, "question": q, "answer": a,
             "reference": ref, "review_status": "author-written, needs human review",
             "source": SRC} for i, (t, lang, lvl, q, a, ref) in enumerate(items)]


