def build_changes() -> list[dict]:
    rows = []
    for i, (text, lang, kind, target, value) in enumerate(CHANGES):
        res = evaluate_change(ChangeRequest(kind, target, value))
        rows.append({"id": f"chg-{i:03d}", "text": text, "lang": lang,
                     "structured": {"kind": kind, "target": target, "value": value},
                     "expected_decision": res.decision.value, "reason": res.reason,
                     "source": "texts: " + SRC + "; decisions: generated-by-real-change_policy"})
    return rows


