def build_memory() -> list[dict]:
    rows = [{"id": f"mem-{i:03d}", "text": t, "expected_verdict": v, "category": c,
             "label_source": "hand-labelled", "filter_currently_misses": False, "source": SRC}
            for i, (t, v, c) in enumerate(MEMORY)]
    n = len(rows)
    rows += [{"id": f"mem-{n + j:03d}", "text": t, "expected_verdict": v, "category": c,
              "label_source": "hand-labelled", "filter_currently_misses": True, "source": SRC}
             for j, (t, v, c) in enumerate(KNOWN_GAPS)]
    return rows


